// Changes: Tests of the export entry point (kind → text / image / error), the C headers and the export inputs.

import { describe, expect, it } from 'vitest'
import { analyzeGrammar } from './analysis'
import { EXPORTS, buildExport, exportInputs, type ExportKind } from './exports'
import { loadPrecExample } from './precOps'
import { defaultProjectData, type ProjectData } from './project'

const grammarOf = (d: ProjectData) => analyzeGrammar({ rules: d.ll.grammar, ...d.def })

function filled(): ProjectData {
  const d = loadPrecExample(defaultProjectData())
  return { ...d, ll: { grammar: "E -> T E'\nE' -> + T E' | ε\nT -> ( E ) | i", input: '' } }
}

const build = (kind: ExportKind, d = filled()) => buildExport(kind, d, grammarOf(d))

describe('buildExport', () => {
  it('gives a result for every listed kind of a filled project', () => {
    for (const { kind } of EXPORTS) expect(build(kind).type, kind).not.toBe('error')
  })

  it('renders the LL table as an image table (regression: ll-png used to be an unknown format)', () => {
    const r = build('ll-png')
    expect(r.type).toBe('image')
    if (r.type !== 'image') return
    expect(r.name).toBe('ll-table.png')
    expect(r.table.title).toBe('LL tabuľka')
    expect(r.table.header).toEqual(['', '+', '(', ')', 'i', '$'])
  })

  it('renders the precedence table as an image table', () => {
    const r = build('prec-png')
    expect(r.type === 'image' && r.table.header).toEqual(['', 'i', '+', '*', '(', ')', '$'])
  })

  it('reports an empty table instead of exporting it', () => {
    const d = defaultProjectData()
    expect(build('prec-png', d)).toEqual({ type: 'error', error: 'Precedenčná tabuľka je prázdna.' })
    expect(build('prec-csv', d)).toEqual({ type: 'error', error: 'Precedenčná tabuľka je prázdna.' })
    expect(build('ll-png', d)).toEqual({ type: 'error', error: 'LL gramatika je prázdna.' })
    expect(build('def-md', d)).toEqual({ type: 'error', error: 'Definícia gramatiky je prázdna.' })
  })

  it('gives text exports a file name and a media type', () => {
    expect(build('prec-csv')).toMatchObject({ type: 'text', name: 'prec-table.csv', mime: 'text/csv;charset=utf-8' })
    expect(build('ll-md')).toMatchObject({ type: 'text', name: 'll-table.md', mime: 'text/markdown;charset=utf-8' })
    const csv = build('prec-csv')
    expect(csv.type === 'text' && csv.text.split('\n').slice(0, 2)).toEqual([',i,+,*,(,),$', 'i,,>,>,,>,>'])
  })

  it('adds a preview to the LaTeX exports only', () => {
    const tex = build('ll-tex')
    expect(tex.type === 'text' && tex.preview).toMatchObject({ type: 'table', header: ['', '+', '(', ')', 'i', '$'] })
    const def = build('def-tex')
    expect(def.type === 'text' && def.preview).toMatchObject({ type: 'def', N: ['E', "E'", 'T'] })
    const md = build('ll-md')
    expect(md.type === 'text' && md.preview).toBeUndefined()
  })
})

describe('C headers', () => {
  // Enumerator names declared inside `typedef enum { … }` blocks.
  const enumerators = (c: string) =>
    [...c.matchAll(/typedef enum \{([^}]*)\}/g)].flatMap((m) => [...m[1].matchAll(/^\s+([A-Za-z_]\w*)/gm)].map((x) => x[1]))
  const headers = (d: ProjectData) => {
    const ll = build('ll-c', d)
    const prec = build('prec-c', d)
    if (ll.type !== 'text' || prec.type !== 'text') throw new Error('no header')
    return { ll: enumerators(ll.text), prec: enumerators(prec.text) }
  }

  it('can be included together: no enum constant is defined in both headers', () => {
    const d = filled()
    d.names.map = '+ PLUS_SIGN\ni IDENT\n$ END'
    const { ll, prec } = headers(d)
    expect(ll).toContain('T_PLUS_SIGN')
    expect(prec).toContain('PT_PLUS_SIGN')
    expect(ll.filter((n) => prec.includes(n))).toEqual([])
  })

  it('keeps a custom name that already carries the header prefix', () => {
    const d = filled()
    d.names.map = 'i T_ID'
    const { ll, prec } = headers(d)
    expect(ll).toContain('T_ID')
    expect(prec).toContain('PT_T_ID')
  })

  it('never reuses a fixed identifier of the header for a symbol', () => {
    const d = filled()
    d.ll.grammar = 'E -> COUNT'
    d.names.precPrefix = 'PREC_'
    d.prec = { ...d.prec, terminals: ['<', 'NONE'] }
    const { ll, prec } = headers(d)
    expect(new Set(ll).size).toBe(ll.length)
    expect(new Set(prec).size).toBe(prec.length)
  })
})

describe('exportInputs', () => {
  // Changing what an export does not read must not change its output (so the UI can skip rebuilding it).
  it('lists everything each export reads', () => {
    const d = filled()
    const other: ProjectData = {
      ...defaultProjectData(),
      ll: { grammar: 'X -> y', input: 'y' },
      names: { map: 'i ZZ', ntPrefix: 'A_', tPrefix: 'B_', precPrefix: 'C_' },
    }
    for (const { kind } of EXPORTS) {
      const reads = exportInputs(kind, d, grammarOf(d))
      const mixed: ProjectData = {
        ...d,
        prec: reads.prec ? d.prec : other.prec,
        names: reads.names ? d.names : other.names,
        ll: reads.grammar ? d.ll : other.ll,
      }
      expect(buildExport(kind, mixed, reads.grammar ? grammarOf(d) : grammarOf(mixed)), kind).toEqual(build(kind, d))
    }
  })

  it('keeps the PNG of the precedence table independent of the C names', () => {
    const d = filled()
    expect(exportInputs('prec-png', d, grammarOf(d))).toEqual({ grammar: null, prec: d.prec, names: null })
  })
})
